20	constexpr uint32_t kMinClientPort = 1U;
21	constexpr uint32_t kMaxPort = 65535U;
22	
23	HixlStatus HixlCSServerCreate(const HixlServerDesc *server_desc, const HixlServerConfig *config,
24	                              HixlServerHandle *server_handle) {
25	  HIXL_CHECK_NOTNULL(server_handle);
26	  *server_handle = nullptr;
27	  HIXL_CHECK_NOTNULL(server_desc);
28	  HIXL_CHECK_NOTNULL(server_desc->server_ip);
29	  HIXL_CHECK_NOTNULL(config);
30	  HIXL_CHK_BOOL_RET_STATUS(server_desc->server_port <= kMaxPort, HIXL_PARAM_INVALID,
31	                           "[HixlCSServerCreate] server_port out of range: %u, must be in [0, %u]",
32	                           server_desc->server_port, kMaxPort);
33	  hixl::GlobalConfig global_config;
34	  HIXL_CHK_STATUS_RET(hixl::GlobalConfig::Parse(config->global_resource_config, global_config,
35	                                                hixl::GlobalConfig::ParseTarget::kServer),
36	                      "Failed to parse hixl cs server global_resource_config");
37	  auto server = new (std::nothrow) hixl::HixlCSServer(server_desc->server_ip, server_desc->server_port, global_config);
38	  HIXL_CHECK_NOTNULL(server);
39	  HIXL_DISMISSABLE_GUARD(rollback, ([server]() { delete server; }));
40	  HIXL_CHK_STATUS_RET(server->Initialize(server_desc->endpoint_list, server_desc->endpoint_list_num),
41	                      "Failed to init hixl cs server, ip:%s, port:%u", server_desc->server_ip,
42	                      server_desc->server_port);
43	  HIXL_DISMISS_GUARD(rollback);
44	  *server_handle = server;
45	  HIXL_EVENT("[HixlCSServer] create server success, server_handle:%p", *server_handle);
46	  return HIXL_SUCCESS;
47	}
48	
49	HixlStatus HixlCSServerDestroy(HixlServerHandle server_handle) {
50	  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
51	  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
52	  HIXL_MAKE_GUARD(release, ([server]() { delete server; }));
53	  HIXL_CHK_STATUS_RET(server->Finalize(), "Failed to finalize hixl cs server, server_handle:%p", server_handle);
54	  return HIXL_SUCCESS;
55	}
56	
57	HixlStatus HixlCSServerRegMem(HixlServerHandle server_handle, const char *mem_tag, const CommMem *mem,
58	                              MemHandle *mem_handle) {
59	  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
60	  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
61	  HIXL_CHECK_NOTNULL(mem);
62	  HIXL_CHECK_NOTNULL(mem_handle);
63	  HIXL_CHK_STATUS_RET(server->RegisterMem(mem_tag, mem, mem_handle), "Failed to register server mem");
64	  return HIXL_SUCCESS;
65	}
66	
67	HixlStatus HixlCSServerUnregMem(HixlServerHandle server_handle, MemHandle mem_handle) {
68	  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
69	  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
70	  HIXL_CHECK_NOTNULL(mem_handle);
71	  HIXL_CHK_STATUS_RET(server->DeregisterMem(mem_handle), "Failed to deregister server mem, mem_handle:%p", mem_handle);
72	  return HIXL_SUCCESS;
73	}
74	
75	HixlStatus HixlCSServerListen(HixlServerHandle server_handle, uint32_t backlog) {
76	  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
77	  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
78	  HIXL_CHK_STATUS_RET(server->Listen(backlog), "Failed to start server listen, backlog:%u", backlog);
79	  return HIXL_SUCCESS;
80	}
81	
82	HixlStatus HixlCSClientCreate(const HixlClientDesc *client_desc, const HixlClientConfig *config,
83	                              HixlClientHandle *client_handle) {
84	  HIXL_CHECK_NOTNULL(client_handle);
85	  *client_handle = nullptr;
86	  HIXL_CHECK_NOTNULL(client_desc);
87	  HIXL_CHECK_NOTNULL(client_desc->server_ip);
88	  HIXL_CHECK_NOTNULL(client_desc->local_endpoint);
89	  HIXL_CHECK_NOTNULL(client_desc->remote_endpoint);
90	  HIXL_CHECK_NOTNULL(config);
91	  HIXL_CHK_BOOL_RET_STATUS(client_desc->server_port >= kMinClientPort && client_desc->server_port <= kMaxPort,
92	                           HIXL_PARAM_INVALID, "[HixlCSClientCreate] server_port out of range: %u, must be in [%u, %u]",
93	                           client_desc->server_port, kMinClientPort, kMaxPort);
94	  auto *client = new (std::nothrow) hixl::HixlCSClient();
95	  HIXL_CHECK_NOTNULL(client);
96	  HIXL_DISMISSABLE_GUARD(rollback, ([client]() { delete client; }));
97	  HIXL_CHK_STATUS_RET(client->Create(client_desc, config),
98	                      "Failed to create hixl cs client, "
99	                      "server_ip:%s, server_port:%u",
100	                      client_desc->server_ip, client_desc->server_port);
101	  *client_handle = static_cast<HixlClientHandle>(client);
102	  HIXL_DISMISS_GUARD(rollback);
103	  return HIXL_SUCCESS;
104	}
105	
106	HixlStatus HixlCSClientRegMem(HixlClientHandle client_handle, const char *mem_tag, const CommMem *mem,
107	                              MemHandle *mem_handle) {
108	  HIXL_CHECK_NOTNULL(client_handle);
109	  HIXL_CHECK_NOTNULL(mem);
110	  HIXL_CHECK_NOTNULL(mem_handle);
111	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
112	  HIXL_CHK_STATUS_RET(client->RegMem(mem_tag, mem, mem_handle),
113	                      "HixlCSClientRegMem failed, client_handle is %p, mem_tag: %s, mem_addr: %p, mem_size: %lu.",
114	                      client_handle, (mem_tag != nullptr ? mem_tag : "(null)"), mem->addr, mem->size);
115	  return HIXL_SUCCESS;
116	}
117	
118	HixlStatus HixlCSClientUnregMem(HixlClientHandle client_handle, MemHandle mem_handle) {
119	  HIXL_CHECK_NOTNULL(client_handle);
120	  HIXL_CHECK_NOTNULL(mem_handle);
121	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
122	  HIXL_CHK_STATUS_RET(client->UnRegMem(mem_handle), "HixlCSClientUnregMem failed, client_handle is %p.", client_handle);
123	  return HIXL_SUCCESS;
124	}
125	
126	HixlStatus HixlCSClientBatchPutAsync(HixlClientHandle client_handle, uint32_t list_num,
127	                                     const HixlOneSideOpDesc *desc_list, CompleteHandle *complete_handle) {
128	  HIXL_CHECK_NOTNULL(client_handle);
129	  if (list_num > 0) {
130	    HIXL_CHECK_NOTNULL(desc_list);
131	  } else {
132	    HIXL_LOGE(HIXL_PARAM_INVALID,
133	              "[HixlCSClientBatchPutAsync] The value of list_num is invalid. client_handle is %p, list_num: %u",
134	              client_handle, list_num);
135	    return HIXL_PARAM_INVALID;
136	  }
137	  HIXL_CHECK_NOTNULL(complete_handle);
138	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
139	  void *raw_handle = nullptr;
140	  const auto ret = client->BatchTransferAsync(false, list_num, desc_list, &raw_handle);
141	  if (raw_handle != nullptr) {
142	    *complete_handle = raw_handle;
143	    HIXL_LOGI("HixlCSClientBatchPutAsync complete_handle create, complete_handle is %p.", complete_handle);
144	  }
145	  HIXL_CHK_STATUS_RET(ret, "HixlCSClientBatchPutAsync failed, client_handle is %p, list_num:%u", client_handle,
146	                      list_num);
147	  return HIXL_SUCCESS;
148	}
149	
150	HixlStatus HixlCSClientBatchGetAsync(HixlClientHandle client_handle, uint32_t list_num,
151	                                     const HixlOneSideOpDesc *desc_list, CompleteHandle *complete_handle) {
152	  HIXL_CHECK_NOTNULL(client_handle);
153	  if (list_num > 0) {
154	    HIXL_CHECK_NOTNULL(desc_list);
155	  } else {
156	    HIXL_LOGE(HIXL_PARAM_INVALID,
157	              "[HixlCSClientBatchGetAsync] The value of list_num is invalid. client_handle is %p, list_num: %u",
158	              client_handle, list_num);
159	    return HIXL_PARAM_INVALID;
160	  }
161	  HIXL_CHECK_NOTNULL(complete_handle);
162	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
163	  void *raw_handle = nullptr;
164	  const auto ret = client->BatchTransferAsync(true, list_num, desc_list, &raw_handle);
165	  if (raw_handle != nullptr) {
166	    *complete_handle = raw_handle;
167	    HIXL_LOGI("HixlCSClientBatchGetAsync complete_handle create, complete_handle is %p.", complete_handle);
168	  }
169	  HIXL_CHK_STATUS_RET(ret, "HixlCSClientBatchGetAsync failed, client_handle is %p, list_num:%u", client_handle,
170	                      list_num);
171	  return HIXL_SUCCESS;
172	}
173	
174	HixlStatus HixlCSClientBatchPutSync(HixlClientHandle client_handle, uint32_t list_num,
175	                                    const HixlOneSideOpDesc *desc_list, uint32_t timeout_ms) {
176	  HIXL_CHECK_NOTNULL(client_handle);
177	  if (list_num > 0) {
178	    HIXL_CHECK_NOTNULL(desc_list);
179	  } else {
180	    HIXL_LOGE(HIXL_PARAM_INVALID,
181	              "[HixlCSClientBatchPutSync] The value of list_num is invalid. client_handle is %p, list_num: %u",
182	              client_handle, list_num);
183	    return HIXL_PARAM_INVALID;
184	  }
185	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
186	  HIXL_CHK_STATUS_RET(client->BatchTransferSync(false, list_num, desc_list, timeout_ms),
187	                      "HixlCSClientBatchPutSync failed, client_handle is %p, list_num:%u", client_handle, list_num);
188	  return HIXL_SUCCESS;
189	}
190	
191	HixlStatus HixlCSClientBatchGetSync(HixlClientHandle client_handle, uint32_t list_num,
192	                                    const HixlOneSideOpDesc *desc_list, uint32_t timeout_ms) {
193	  HIXL_CHECK_NOTNULL(client_handle);
194	  if (list_num > 0) {
195	    HIXL_CHECK_NOTNULL(desc_list);
196	  } else {
197	    HIXL_LOGE(HIXL_PARAM_INVALID,
198	              "[HixlCSClientBatchGetSync] The value of list_num is invalid. client_handle is %p, list_num: %u",
199	              client_handle, list_num);
200	    return HIXL_PARAM_INVALID;
201	  }
202	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
203	  HIXL_CHK_STATUS_RET(client->BatchTransferSync(true, list_num, desc_list, timeout_ms),
204	                      "HixlCSClientBatchGetSync failed, client_handle is %p, list_num:%u", client_handle, list_num);
205	  return HIXL_SUCCESS;
206	}
207	
208	HixlStatus HixlCSClientQueryCompleteStatus(HixlClientHandle client_handle, CompleteHandle complete_handle,
209	                                           HixlCompleteStatus *complete_status) {
210	  HIXL_CHECK_NOTNULL(client_handle);
211	  HIXL_CHECK_NOTNULL(complete_handle);
212	  HIXL_CHECK_NOTNULL(complete_status);
213	  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
214	  HIXL_CHK_STATUS_RET(client->CheckStatus(complete_handle, complete_status),
215	                      "HixlCSClientQueryCompleteStatus failed, client_handle is %p.", client_handle);
216	  return HIXL_SUCCESS;
217	}
218	
219	HixlStatus HixlCSClientConnect(HixlClientHandle client_handle, uint32_t timeout_ms) {
220	  HIXL_CHECK_NOTNULL(client_handle);
221	  auto *client = static_cast<hixl::HixlCSClient *>(client_handle);
222	  HIXL_CHECK_NOTNULL(client);
223	  HIXL_CHK_STATUS_RET(client->Connect(timeout_ms), "HixlCSClientConnect failed, client_handle is %p, timeout:%u ms",
224	                      client_handle, timeout_ms);
225	  return HIXL_SUCCESS;
