#include "cs/hixl_cs.h"
#include "hixl/hixl_types.h"
#include "common/hixl_log.h"
#include "common/ctrl_msg.h"
#include "common/hixl_checker.h"
#include "common/scope_guard.h"
#include "hixl_cs_server.h"
#include "hixl_cs_client.h"

constexpr uint32_t kMinClientPort = 1U;
constexpr uint32_t kMaxPort = 65535U;

HixlStatus HixlCSServerCreate(const HixlServerDesc *server_desc, const HixlServerConfig *config,
                              HixlServerHandle *server_handle) {
  HIXL_CHECK_NOTNULL(server_handle);
  *server_handle = nullptr;
  HIXL_CHECK_NOTNULL(server_desc);
  HIXL_CHECK_NOTNULL(server_desc->server_ip);
  HIXL_CHECK_NOTNULL(config);
  HIXL_CHK_BOOL_RET_STATUS(server_desc->server_port <= kMaxPort, HIXL_PARAM_INVALID,
                           "[HixlCSServerCreate] server_port out of range: %u, must be in [0, %u]",
                           server_desc->server_port, kMaxPort);
  hixl::GlobalConfig global_config;
  HIXL_CHK_STATUS_RET(hixl::GlobalConfig::Parse(config->global_resource_config, global_config,
                                                hixl::GlobalConfig::ParseTarget::kServer),
                      "Failed to parse hixl cs server global_resource_config");
  auto server = new (std::nothrow) hixl::HixlCSServer(server_desc->server_ip, server_desc->server_port, global_config);
  HIXL_CHECK_NOTNULL(server);
  HIXL_DISMISSABLE_GUARD(rollback, ([server]() { delete server; }));
  HIXL_CHK_STATUS_RET(server->Initialize(server_desc->endpoint_list, server_desc->endpoint_list_num),
                      "Failed to init hixl cs server, ip:%s, port:%u", server_desc->server_ip,
                      server_desc->server_port);
  HIXL_DISMISS_GUARD(rollback);
  *server_handle = server;
  HIXL_EVENT("[HixlCSServer] create server success, server_handle:%p", *server_handle);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSServerDestroy(HixlServerHandle server_handle) {
  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
  HIXL_MAKE_GUARD(release, ([server]() { delete server; }));
  HIXL_CHK_STATUS_RET(server->Finalize(), "Failed to finalize hixl cs server, server_handle:%p", server_handle);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSServerRegMem(HixlServerHandle server_handle, const char *mem_tag, const CommMem *mem,
                              MemHandle *mem_handle) {
  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
  HIXL_CHECK_NOTNULL(mem);
  HIXL_CHECK_NOTNULL(mem_handle);
  HIXL_CHK_STATUS_RET(server->RegisterMem(mem_tag, mem, mem_handle), "Failed to register server mem");
  return HIXL_SUCCESS;
}

HixlStatus HixlCSServerUnregMem(HixlServerHandle server_handle, MemHandle mem_handle) {
  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
  HIXL_CHECK_NOTNULL(mem_handle);
  HIXL_CHK_STATUS_RET(server->DeregisterMem(mem_handle), "Failed to deregister server mem, mem_handle:%p", mem_handle);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSServerListen(HixlServerHandle server_handle, uint32_t backlog) {
  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
  HIXL_CHK_STATUS_RET(server->Listen(backlog), "Failed to start server listen, backlog:%u", backlog);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientCreate(const HixlClientDesc *client_desc, const HixlClientConfig *config,
                              HixlClientHandle *client_handle) {
  HIXL_CHECK_NOTNULL(client_handle);
  *client_handle = nullptr;
  HIXL_CHECK_NOTNULL(client_desc);
  HIXL_CHECK_NOTNULL(client_desc->server_ip);
  HIXL_CHECK_NOTNULL(client_desc->local_endpoint);
  HIXL_CHECK_NOTNULL(client_desc->remote_endpoint);
  HIXL_CHECK_NOTNULL(config);
  HIXL_CHK_BOOL_RET_STATUS(client_desc->server_port >= kMinClientPort && client_desc->server_port <= kMaxPort,
                           HIXL_PARAM_INVALID, "[HixlCSClientCreate] server_port out of range: %u, must be in [%u, %u]",
                           client_desc->server_port, kMinClientPort, kMaxPort);
  auto *client = new (std::nothrow) hixl::HixlCSClient();
  HIXL_CHECK_NOTNULL(client);
  HIXL_DISMISSABLE_GUARD(rollback, ([client]() { delete client; }));
  HIXL_CHK_STATUS_RET(client->Create(client_desc, config),
                      "Failed to create hixl cs client, "
                      "server_ip:%s, server_port:%u",
                      client_desc->server_ip, client_desc->server_port);
  *client_handle = static_cast<HixlClientHandle>(client);
  HIXL_DISMISS_GUARD(rollback);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientRegMem(HixlClientHandle client_handle, const char *mem_tag, const CommMem *mem,
                              MemHandle *mem_handle) {
  HIXL_CHECK_NOTNULL(client_handle);
  HIXL_CHECK_NOTNULL(mem);
  HIXL_CHECK_NOTNULL(mem_handle);
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHK_STATUS_RET(client->RegMem(mem_tag, mem, mem_handle),
                      "HixlCSClientRegMem failed, client_handle is %p, mem_tag: %s, mem_addr: %p, mem_size: %lu.",
                      client_handle, (mem_tag != nullptr ? mem_tag : "(null)"), mem->addr, mem->size);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientUnregMem(HixlClientHandle client_handle, MemHandle mem_handle) {
  HIXL_CHECK_NOTNULL(client_handle);
  HIXL_CHECK_NOTNULL(mem_handle);
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHK_STATUS_RET(client->UnRegMem(mem_handle), "HixlCSClientUnregMem failed, client_handle is %p.", client_handle);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientBatchPutAsync(HixlClientHandle client_handle, uint32_t list_num,
                                     const HixlOneSideOpDesc *desc_list, CompleteHandle *complete_handle) {
  HIXL_CHECK_NOTNULL(client_handle);
  if (list_num > 0) {
    HIXL_CHECK_NOTNULL(desc_list);
  } else {
    HIXL_LOGE(HIXL_PARAM_INVALID,
              "[HixlCSClientBatchPutAsync] The value of list_num is invalid. client_handle is %p, list_num: %u",
              client_handle, list_num);
    return HIXL_PARAM_INVALID;
  }
  HIXL_CHECK_NOTNULL(complete_handle);
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  void *raw_handle = nullptr;
  const auto ret = client->BatchTransferAsync(false, list_num, desc_list, &raw_handle);
  if (raw_handle != nullptr) {
    *complete_handle = raw_handle;
    HIXL_LOGI("HixlCSClientBatchPutAsync complete_handle create, complete_handle is %p.", complete_handle);
  }
  HIXL_CHK_STATUS_RET(ret, "HixlCSClientBatchPutAsync failed, client_handle is %p, list_num:%u", client_handle,
                      list_num);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientBatchGetAsync(HixlClientHandle client_handle, uint32_t list_num,
                                     const HixlOneSideOpDesc *desc_list, CompleteHandle *complete_handle) {
  HIXL_CHECK_NOTNULL(client_handle);
  if (list_num > 0) {
    HIXL_CHECK_NOTNULL(desc_list);
  } else {
    HIXL_LOGE(HIXL_PARAM_INVALID,
              "[HixlCSClientBatchGetAsync] The value of list_num is invalid. client_handle is %p, list_num: %u",
              client_handle, list_num);
    return HIXL_PARAM_INVALID;
  }
  HIXL_CHECK_NOTNULL(complete_handle);
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  void *raw_handle = nullptr;
  const auto ret = client->BatchTransferAsync(true, list_num, desc_list, &raw_handle);
  if (raw_handle != nullptr) {
    *complete_handle = raw_handle;
    HIXL_LOGI("HixlCSClientBatchGetAsync complete_handle create, complete_handle is %p.", complete_handle);
  }
  HIXL_CHK_STATUS_RET(ret, "HixlCSClientBatchGetAsync failed, client_handle is %p, list_num:%u", client_handle,
                      list_num);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientBatchPutSync(HixlClientHandle client_handle, uint32_t list_num,
                                    const HixlOneSideOpDesc *desc_list, uint32_t timeout_ms) {
  HIXL_CHECK_NOTNULL(client_handle);
  if (list_num > 0) {
    HIXL_CHECK_NOTNULL(desc_list);
  } else {
    HIXL_LOGE(HIXL_PARAM_INVALID,
              "[HixlCSClientBatchPutSync] The value of list_num is invalid. client_handle is %p, list_num: %u",
              client_handle, list_num);
    return HIXL_PARAM_INVALID;
  }
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHK_STATUS_RET(client->BatchTransferSync(false, list_num, desc_list, timeout_ms),
                      "HixlCSClientBatchPutSync failed, client_handle is %p, list_num:%u", client_handle, list_num);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientBatchGetSync(HixlClientHandle client_handle, uint32_t list_num,
                                    const HixlOneSideOpDesc *desc_list, uint32_t timeout_ms) {
  HIXL_CHECK_NOTNULL(client_handle);
  if (list_num > 0) {
    HIXL_CHECK_NOTNULL(desc_list);
  } else {
    HIXL_LOGE(HIXL_PARAM_INVALID,
              "[HixlCSClientBatchGetSync] The value of list_num is invalid. client_handle is %p, list_num: %u",
              client_handle, list_num);
    return HIXL_PARAM_INVALID;
  }
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHK_STATUS_RET(client->BatchTransferSync(true, list_num, desc_list, timeout_ms),
                      "HixlCSClientBatchGetSync failed, client_handle is %p, list_num:%u", client_handle, list_num);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientQueryCompleteStatus(HixlClientHandle client_handle, CompleteHandle complete_handle,
                                           HixlCompleteStatus *complete_status) {
  HIXL_CHECK_NOTNULL(client_handle);
  HIXL_CHECK_NOTNULL(complete_handle);
  HIXL_CHECK_NOTNULL(complete_status);
  auto client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHK_STATUS_RET(client->CheckStatus(complete_handle, complete_status),
                      "HixlCSClientQueryCompleteStatus failed, client_handle is %p.", client_handle);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientConnect(HixlClientHandle client_handle, uint32_t timeout_ms) {
  HIXL_CHECK_NOTNULL(client_handle);
  auto *client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHECK_NOTNULL(client);
  HIXL_CHK_STATUS_RET(client->Connect(timeout_ms), "HixlCSClientConnect failed, client_handle is %p, timeout:%u ms",
                      client_handle, timeout_ms);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientGetRemoteMem(HixlClientHandle client_handle, CommMem **remote_mem_list, char ***mem_tag_list,
                                    uint32_t *list_num, uint32_t timeout_ms) {
  HIXL_CHECK_NOTNULL(client_handle);
  auto *client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHECK_NOTNULL(client);
  HIXL_CHK_STATUS_RET(client->GetRemoteMem(remote_mem_list, mem_tag_list, list_num, timeout_ms),
                      "HixlCSClientGetRemoteMem failed, client_handle is %p, timeout:%u ms", client_handle, timeout_ms);
  return HIXL_SUCCESS;
}

HixlStatus HixlCSClientDestroy(HixlClientHandle client_handle) {
  HIXL_CHECK_NOTNULL(client_handle);
  auto *client = static_cast<hixl::HixlCSClient *>(client_handle);
  HIXL_CHECK_NOTNULL(client);
  HIXL_CHK_STATUS_RET(client->Destroy(), "HixlCSClientDestroy failed, client_handle is %p.", client_handle);
  delete client;
  return HIXL_SUCCESS;
}

namespace hixl {
HixlStatus HixlCSServerRegProc(HixlServerHandle server_handle, hixl::CtrlMsgType msg_type, hixl::MsgProcessor proc) {
  auto server = static_cast<hixl::HixlCSServer *>(server_handle);
  HIXL_CHECK_NOTNULL(server, ", please use handle generated by HixlCSServerCreate");
  HIXL_CHK_STATUS_RET(server->RegProc(msg_type, proc), "Failed to reg proc, msg_type:%d",
                      static_cast<int32_t>(msg_type));
  return HIXL_SUCCESS;
}
}  // namespace hixl

