33	namespace hixl {
34	namespace {
35	constexpr uint32_t kDefaultTransferPoolSize = 128U;  // 与 HixlCSClient 侧设备池大小一致
36	constexpr int32_t kMaxEventsNum = 128;               // epoll_wait并发处理事件数量，减少epoll系统调用
37	constexpr int32_t kEpollWaitTimeInMillis = 100;      // epoll_wait等待超时时间
38	constexpr const char *kTransFlagNameHost = "_hixl_builtin_host_trans_flag";   // client用于感知收发完成的标识
39	constexpr const char *kTransFlagNameDevice = "_hixl_builtin_dev_trans_flag";  // client用于感知收发完成的标识
40	// server端进程级channel索引计数器，用于两端构建一致的channelName
41	std::atomic<uint64_t> g_next_server_channel_index{0UL};
42	
43	bool IsUbEndpoint(CommProtocol protocol) {
44	  return protocol == COMM_PROTOCOL_UBC_TP || protocol == COMM_PROTOCOL_UBC_CTP;
45	}
46	
47	bool IsValidMemType(CommMemType type) {
48	  return type == COMM_MEM_TYPE_HOST || type == COMM_MEM_TYPE_DEVICE;
49	}
50	
51	bool IsDeviceEndpointDesc(const EndpointDesc &endpoint) {
52	  return endpoint.loc.locType == ENDPOINT_LOC_TYPE_DEVICE;
53	}
54	
55	bool IsUbCtpEndpoint(const EndpointDesc &endpoint) {
56	  return endpoint.protocol == COMM_PROTOCOL_UBC_CTP;
57	}
58	
59	bool IsDeviceUbCtpEndpoint(const EndpointDesc &endpoint) {
60	  return IsDeviceEndpointDesc(endpoint) && IsUbCtpEndpoint(endpoint);
61	}
62	
63	bool IsDeviceUboeEndpoint(const EndpointDesc &endpoint) {
64	  return IsDeviceEndpointDesc(endpoint) && endpoint.protocol == COMM_PROTOCOL_UBOE;
65	}
66	
67	bool IsDeviceUbgEndpoint(const EndpointDesc &endpoint) {
68	  return IsDeviceEndpointDesc(endpoint) && endpoint.protocol == COMM_PROTOCOL_UBG;
69	}
70	
71	bool AreUbCtpEndpointsAllDevice(const EndpointDesc *endpoint_list, uint32_t list_num) {
72	  for (uint32_t i = 0U; i < list_num; ++i) {
73	    if (IsUbCtpEndpoint(endpoint_list[i]) && !IsDeviceEndpointDesc(endpoint_list[i])) {
74	      return false;
75	    }
76	  }
77	  return true;
78	}
79	
80	bool NeedServerHostVaMapping(const EndpointDesc &endpoint, bool ub_ctp_endpoints_all_device) {
81	  return IsDeviceUboeEndpoint(endpoint) || IsDeviceUbgEndpoint(endpoint) ||
82	         (ub_ctp_endpoints_all_device && IsDeviceUbCtpEndpoint(endpoint));
83	}
84	
85	bool ShouldRegisterEndpointForMem(const EndpointPtr &endpoint, CommMemType mem_type) {
86	  const auto &endpoint_desc = endpoint->GetEndpoint();
87	  if (!IsUbEndpoint(endpoint_desc.protocol)) {
88	    return true;
89	  }
90	  if (mem_type == COMM_MEM_TYPE_HOST) {
91	    return endpoint_desc.loc.locType == ENDPOINT_LOC_TYPE_HOST || endpoint->NeedHostVaMapping();
92	  }
93	  if (mem_type == COMM_MEM_TYPE_DEVICE) {
94	    return endpoint_desc.loc.locType == ENDPOINT_LOC_TYPE_DEVICE;
95	  }
96	  return false;
97	}
