100	std::unique_ptr<hixl::TemporaryRtContext> HixlCSServer::GetContextGuard() const {
101	  if (device_id_ >= 0) {
102	    auto *pool = TransferPool::GetInstance(device_id_);
103	    if (pool == nullptr) {
104	      return nullptr;
105	    }
106	    aclrtContext ctx = pool->GetContext();
107	    if (ctx != nullptr) {
108	      return MakeUnique<hixl::TemporaryRtContext>(ctx);
109	    }
110	  }
111	  return nullptr;  // 不切换 context
112	}
113	
114	Status HixlCSServer::InitTransFinishedFlag() {
115	  std::vector<EndpointPtr> host_endpoints;
116	  std::vector<EndpointPtr> device_endpoints;
117	  bool has_non_hccs_device_ep = false;
118	  for (auto handle : endpoint_store_.GetAllEndpointHandles()) {
119	    auto endpoint = endpoint_store_.GetEndpoint(handle);
120	    if (endpoint == nullptr) {
121	      continue;
122	    }
123	    const auto &desc = endpoint->GetEndpoint();
124	    if (desc.loc.locType == ENDPOINT_LOC_TYPE_HOST) {
125	      host_endpoints.emplace_back(std::move(endpoint));
126	    } else if (desc.loc.locType == ENDPOINT_LOC_TYPE_DEVICE) {
127	      if (desc.protocol != COMM_PROTOCOL_HCCS) {
128	        has_non_hccs_device_ep = true;
129	      }
130	      device_endpoints.emplace_back(std::move(endpoint));
131	    }
132	  }
133	  if (!host_endpoints.empty()) {
134	    HIXL_CHK_STATUS_RET(RegisterHostTransFinishedFlag(host_endpoints), "Failed to reg HOST trans finished flag");
135	  }
136	  if (!device_endpoints.empty()) {
137	    HIXL_CHK_STATUS_RET(RegisterDeviceTransFinishedFlag(device_endpoints, has_non_hccs_device_ep),
138	                        "Failed to reg DEVICE trans finished flag");
139	  }
140	  return SUCCESS;
141	}
142	
143	Status HixlCSServer::RegisterHostTransFinishedFlag(const std::vector<EndpointPtr> &host_endpoints) {
144	  void *host_flag = nullptr;
145	  int64_t page_size = sysconf(_SC_PAGESIZE);
146	  HIXL_CHK_BOOL_RET_STATUS(page_size > 0, FAILED, "sysconf(_SC_PAGESIZE) failed, errno=%d, errmsg=%s", errno,
147	                           strerror(errno));
148	  size_t align_size = static_cast<size_t>(page_size);
149	  // Register host mem addr need aligned by page size.
150	  int ret = posix_memalign(&host_flag, align_size, sizeof(int64_t));
151	  HIXL_CHK_BOOL_RET_STATUS(ret == 0 && host_flag != nullptr, FAILED,
152	                           "HOST trans finished flag posix_memalign failed, ret:%d, page_size=%zu, alloc size=%zu.",
153	                           ret, align_size, sizeof(int64_t));
154	  HIXL_DISMISSABLE_GUARD(host_flag_guard, ([host_flag]() { free(host_flag); }));
155	  *static_cast<int64_t *>(host_flag) = 1;
156	  CommMem mem{};
157	  mem.type = COMM_MEM_TYPE_HOST;
158	  mem.addr = host_flag;
159	  mem.size = sizeof(int64_t);
160	  for (const auto &endpoint : host_endpoints) {
161	    MemHandle ep_mem_handle = nullptr;
162	    HIXL_CHK_STATUS_RET(endpoint->RegisterMem(kTransFlagNameHost, mem, ep_mem_handle),
163	                        "Failed to reg HOST trans finished flag");
164	  }
165	  host_trans_flag_ = host_flag;
166	  HIXL_DISMISS_GUARD(host_flag_guard);
167	  return SUCCESS;
168	}
169	
170	Status HixlCSServer::RegisterDeviceTransFinishedFlag(const std::vector<EndpointPtr> &device_endpoints,
171	                                                     bool resolve_notify_addr) {
172	  int32_t dev_id = 0;
173	  HIXL_CHK_ACL_RET(aclrtGetDevice(&dev_id), "Failed to aclrtGetDevice for CS server TransferPool");
174	  hixl::TemporaryRtContext with_context(nullptr);  // 创建context会切换当前context, 因此需要在析构时恢复原用户context
175	  auto *pool = TransferPool::GetInstance(dev_id);
176	  HIXL_CHECK_NOTNULL(pool);
177	  HIXL_CHK_STATUS_RET(pool->Initialize(global_config_.MaxActiveChannels().value_or(kDefaultTransferPoolSize)),
178	                      "Failed to init TransferPool for CS server, dev_id:%d", dev_id);
179	  HIXL_DISMISSABLE_GUARD(pool_rollback, ([dev_id]() {
180	                           auto *p = TransferPool::GetInstance(dev_id);
181	                           if (p != nullptr) {
182	                             p->Finalize();
183	                           }
184	                         }));
185	  if (resolve_notify_addr) {
186	    HIXL_CHK_STATUS_RET(pool->ResolveNotifyAddr(), "Failed to resolve TransferPool notify address for CS server");
187	  }
188	  void *dev_flag = nullptr;
189	  HIXL_CHK_ACL_RET(
190	      aclrtMalloc(&dev_flag, sizeof(int64_t),
191	                  static_cast<aclrtMemMallocPolicy>(ACL_MEM_TYPE_HIGH_BAND_WIDTH | ACL_MEM_MALLOC_HUGE_ONLY)));
192	  HIXL_DISMISSABLE_GUARD(dev_flag_guard, ([this, &dev_flag]() { FreeDeviceMem(dev_flag); }));
193	  int64_t val = 1;
194	  HIXL_CHK_ACL_RET(aclrtMemcpy(dev_flag, sizeof(int64_t), &val, sizeof(int64_t), ACL_MEMCPY_HOST_TO_DEVICE));
195	  CommMem mem{};
196	  mem.type = COMM_MEM_TYPE_DEVICE;
197	  mem.addr = dev_flag;
198	  mem.size = sizeof(int64_t);
199	  for (const auto &endpoint : device_endpoints) {
200	    MemHandle ep_mem_handle = nullptr;
201	    HIXL_CHK_STATUS_RET(endpoint->RegisterMem(kTransFlagNameDevice, mem, ep_mem_handle),
202	                        "Failed to reg DEVICE trans finished flag");
203	  }
204	  dev_trans_flag_ = dev_flag;
205	  HIXL_DISMISS_GUARD(dev_flag_guard);
206	  HIXL_DISMISS_GUARD(pool_rollback);
207	  device_id_ = dev_id;
208	  return SUCCESS;
209	}
