273	Status HixlCSServer::Finalize() {
274	  HIXL_LOGI("[HixlServer] finalize begin");
275	  Status ret = SUCCESS;
276	  // ctx_guard 在 TransferPool::Finalize() 之前必须析构，否则 Finalize 会销毁 rts_context_
277	  // 而 ctx_guard 析构时需要恢复到之前的 context，如果之前 context 和 rts_context_ 相同会报错
278	  {
279	    auto ctx_guard = GetContextGuard();
280	    (void)ctx_guard;
281	    if (listener_running_) {
282	      listener_running_ = false;
283	      if (listener_.joinable()) {
284	        listener_.join();
285	      }
286	    }
287	    msg_handler_.Finalize();
288	    ret = endpoint_store_.Finalize();
289	    HIXL_CHK_STATUS(ret, "Failed to finalize endpoint store.");
290	    if (host_trans_flag_ != nullptr) {
291	      free(host_trans_flag_);
292	      host_trans_flag_ = nullptr;
293	    }
294	    FreeDeviceMem(dev_trans_flag_);
295	  }
296	  // ctx_guard 已析构，现在可以安全销毁 TransferPool
297	  if (device_id_ >= 0) {
298	    auto *pool = TransferPool::GetInstance(device_id_);
299	    if (pool != nullptr) {
300	      pool->Finalize();
301	    }
302	    device_id_ = -1;
303	  }
304	
305	  if (listen_fd_ != -1) {
306	    (void)close(listen_fd_);
307	    listen_fd_ = -1;
308	  }
309	
310	  if (epoll_fd_ != -1) {
311	    (void)close(epoll_fd_);
312	    epoll_fd_ = -1;
313	  }
314	  HIXL_EVENT("[HixlServer] finalize end, ret:%u", ret);
315	  return ret;
316	}
