156	hixl::Status ImportOneDesc(hixl::ImportCtx &ctx, uint32_t idx, hixl::HixlMemDesc &desc) {
157	  CommMem buf{};
158	  hixl::Status ret = ctx.ep->MemImport(desc.export_desc, desc.export_len, buf);
159	  const char *safe_tag = desc.tag.empty() ? "<empty>" : desc.tag.c_str();
160	  if (ret != hixl::SUCCESS) {
161	    HIXL_LOGE(ret, "[HixlClient] MemImport failed, idx=%u, tag=%s", idx, safe_tag);
162	    return ret;
163	  }
164	  ctx.imported.emplace_back(buf);
165	  desc.is_imported = true;
166	  CommMem mem{};
167	  mem.type = desc.mem.type;
168	  mem.addr = desc.mem.addr;
169	  mem.size = desc.mem.size;
170	  bool is_host_mem = desc.mem.type == COMM_MEM_TYPE_HOST;
171	  HIXL_LOGI("[HixlClient] ImportOneDesc desc.tag=%s mem.addr=%p", safe_tag, mem.addr);
172	  ctx.mems.emplace_back(mem);
173	  if (!desc.tag.empty()) {
174	    ctx.tag_mem_map[desc.tag] = mem;
175	  }
176	  HIXL_LOGD("[HixlClient] Imported mem[%u]: tag='%s', addr=%p, size=%llu", idx, safe_tag, mem.addr, mem.size);
177	  ret = ctx.store->RecordMemory(true, mem.addr, static_cast<size_t>(mem.size), is_host_mem, desc.registered_dev_mem);
178	  if (ret == hixl::SUCCESS) {
179	    ctx.recorded_addrs.emplace_back(mem.addr);
180	  } else {
181	    HIXL_LOGE(ret,
182	              "[HixlClient] RecordMemory(server) failed! This memory may have been registered. idx=%u, tag=%s, "
183	              "addr=%p, size=%llu",
184	              idx, safe_tag, mem.addr, mem.size);
185	    return ret;
186	  }
187	  if (!desc.tag.empty()) {
188	    return AppendTagStorage(ctx.tag_storage, desc.tag);
189	  }
190	  return hixl::SUCCESS;
191	}
