247	Status HixlCSClient::InitFlagQueue() noexcept {
248	  if (flag_queue_ != nullptr) {
249	    return SUCCESS;  // 已初始化
250	  }
251	  void *tmp = nullptr;
252	  tmp = malloc(kFlagQueueSize * sizeof(uint64_t));
253	  HIXL_DISMISSABLE_GUARD(free_flag_mem, [&tmp]() {
254	    if (tmp != nullptr) {
255	      free(tmp);
256	      tmp = nullptr;
257	    }
258	  });
259	  HIXL_CHK_BOOL_RET_STATUS(tmp != nullptr, FAILED, "Call api:malloc failed, size:%zu bytes",
260	                           kFlagQueueSize * sizeof(uint64_t));
261	  auto *flag_queue = static_cast<uint64_t *>(tmp);
262	  for (size_t i = 0; i < kFlagQueueSize; ++i) {
263	    flag_queue[i] = 0;
264	  }
265	  CommMem mem{};
266	  mem.type = COMM_MEM_TYPE_HOST;
267	  mem.addr = flag_queue;
268	  mem.size = kFlagQueueSize * sizeof(uint64_t);
269	  MemHandle flag_handle = nullptr;
270	  HIXL_CHK_STATUS_RET(RegMemLocked(kTransFlagNameHost, &mem, &flag_handle),
271	                      "Failed to reg HOST trans finished flag, mem.addr: %p, mem.size: %lu.", mem.addr, mem.size);
272	  flag_queue_ = flag_queue;
273	  top_index_ = kFlagQueueSize;  // 初始化成功后可用
274	  HIXL_DISMISS_GUARD(free_flag_mem);
275	  return SUCCESS;
276	}
