385	Status HixlCSClient::RegMemLocked(const char *mem_tag, const CommMem *mem, MemHandle *mem_handle) {
386	  auto ctx_guard = GetContextGuard();
387	  (void)ctx_guard;
388	  HIXL_CHECK_NOTNULL(mem);
389	  auto check_result = mem_store_.CheckMemoryForRegister(false, mem->addr, mem->size);
390	  if (check_result) {
391	    HIXL_LOGE(PARAM_INVALID,
392	              "[HixlClient] Memory registration failed. This memory may overlap with the already recorded memory. "
393	              "Please check Mem, mem_addr:%p, mem_size:%lu bytes.",
394	              mem->addr, mem->size);
395	    return PARAM_INVALID;
396	  }
397	  MemHandle ep_mem_handle = nullptr;
398	  HIXL_CHK_STATUS_RET(local_endpoint_->RegisterMem(mem_tag, *mem, ep_mem_handle),
399	                      "[HixlClient] Failed to register client endpoint mem.");
400	  *mem_handle = ep_mem_handle;
401	  bool is_host_mem = mem->type == COMM_MEM_TYPE_HOST;
402	  void *register_dev_addr = nullptr;
403	  const auto &local_endpoint_desc = local_endpoint_->GetEndpoint();
404	  if (is_host_mem && local_endpoint_->NeedHostVaMapping()) {
405	    HIXL_CHK_STATUS_RET(HostRegisterProxy::GetRegisteredDeviceAddrByDev(local_endpoint_desc.loc.device.devPhyId,
406	                                                                        mem->addr, register_dev_addr),
407	                        "Failed to get registered device addr, devPhyId=%d, addr=%p",
408	                        local_endpoint_desc.loc.device.devPhyId, mem->addr);
409	  }
410	  // 记录client侧给endpoint分配的内存信息
411	  HIXL_CHK_STATUS_RET(mem_store_.RecordMemory(false, mem->addr, mem->size, is_host_mem, register_dev_addr),
412	                      "[HixlClient] Client record memory failed, mem_addr:%p, mem_size:%lu bytes", mem->addr,
413	                      mem->size);
414	  HIXL_LOGI("[HixlClient] Memory register success. ");
415	  return SUCCESS;
416	}
