452	Status HixlCSClient::TransferWithRetry(bool is_get, uint64_t channel_handle, void *dst_buf, const void *src_buf,
453	                                       uint64_t len) const {
454	  constexpr int64_t kRetryTimeoutMs = 20 * 60 * 1000;  // 20 minutes in milliseconds
455	
456	  auto start_time = std::chrono::steady_clock::now();
457	  int32_t hccl_ret = HCCL_SUCCESS;
458	
459	  while (true) {
460	    if (is_get) {
461	      hccl_ret = HcommProxy::ReadNbiOnThread(static_cast<ThreadHandle>(0), channel_handle, dst_buf, src_buf, len);
462	    } else {
463	      hccl_ret = HcommProxy::WriteNbiOnThread(static_cast<ThreadHandle>(0), channel_handle, dst_buf, src_buf, len);
464	    }
465	
466	    if (hccl_ret == HCCL_SUCCESS) {
467	      return SUCCESS;
468	    }
469	
470	    if (hccl_ret != HCCL_E_AGAIN) {
471	      HIXL_CHK_HCCL_RET(static_cast<HcclResult>(hccl_ret),
472	                        "[HixlClient] Transfer failed, is_get:%d, channel_handle:%lu, dst_addr:%p, src_addr:%p, "
473	                        "mem_len:%lu bytes",
474	                        static_cast<int32_t>(is_get), channel_handle, dst_buf, src_buf, len);
475	    }
476	
477	    // 检查超时
478	    auto current_time = std::chrono::steady_clock::now();
479	    auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(current_time - start_time).count();
480	    HIXL_CHK_BOOL_RET_STATUS(elapsed_ms < kRetryTimeoutMs, TIMEOUT,
481	                             "[HixlClient] Transfer timed out, elapsed:%ld ms, is_get:%d, channel_handle:%lu, "
482	                             "dst_addr:%p, src_addr:%p, mem_len:%lu bytes, hccl_ret:%d",
483	                             elapsed_ms, is_get, channel_handle, dst_buf, src_buf, len, hccl_ret);
484	
485	    HIXL_LOGW("[HixlClient] Transfer ret=%d, retrying. elapsed_ms=%ld, dst_addr=%p, src_addr=%p, len=%lu, is_get=%d.",
486	              hccl_ret, elapsed_ms, dst_buf, src_buf, len, is_get);
487	
488	    // 执行 Fence 后重试，执行Fence后通常极少会出现再次重试的问题
489	    HIXL_CHK_HCCL_RET(
490	        static_cast<HcclResult>(HcommProxy::ChannelFenceOnThread(static_cast<ThreadHandle>(0), channel_handle)),
491	        "[HixlClient] channel_handle:%lu", channel_handle);
492	  }
493	}
