495	Status HixlCSClient::BatchTransferTask(bool is_get, uint32_t list_num, const HixlOneSideOpDesc *desc_list) const {
496	  for (uint32_t i = 0; i < list_num; i++) {
497	    void *dst = is_get ? desc_list[i].local_buf : desc_list[i].remote_buf;
498	    const void *src = is_get ? desc_list[i].remote_buf : desc_list[i].local_buf;
499	    HIXL_CHK_STATUS_RET(TransferWithRetry(is_get, client_channel_handle_, dst, src, desc_list[i].len),
500	                        "[HixlClient] TransferWithRetry failed, is_get:%d, channel_handle:%lu, size:%lu bytes",
501	                        static_cast<int32_t>(is_get), client_channel_handle_, desc_list[i].len);
502	  }
503	  HIXL_CHK_HCCL_RET(
504	      static_cast<HcclResult>(HcommProxy::ChannelFenceOnThread(static_cast<ThreadHandle>(0), client_channel_handle_)),
505	      "[HixlClient] channel_handle:%lu", client_channel_handle_);
506	  return SUCCESS;
507	}
508	Status HixlCSClient::BatchTransferHostAsync(bool is_get, uint32_t list_num, const HixlOneSideOpDesc *desc_list,
509	                                            void **query_handle) {
510	  uint32_t num_chunks = (list_num + kMaxKernelBatchSize - 1U) / kMaxKernelBatchSize;
511	  for (uint32_t chunk_idx = 0U; chunk_idx < num_chunks; ++chunk_idx) {
512	    uint32_t chunk_offset = chunk_idx * kMaxKernelBatchSize;
513	    uint32_t chunk_size = std::min(kMaxKernelBatchSize, list_num - chunk_offset);
514	    HIXL_CHK_STATUS_RET(BatchTransferTask(is_get, chunk_size, desc_list + chunk_offset),
515	                        "[HixlClient] BatchTransferTask failed for chunk %u/%u", chunk_idx, num_chunks);
516	  }
517	  int32_t flag_index = AcquireFlagIndex();
518	  if (flag_index == -1) {
519	    HIXL_LOGE(RESOURCE_EXHAUSTED,
520	              "There are a large number of transfer tasks with no query results, making it impossible to create new "
521	              "transfer tasks.Please first call HixlCSClientQueryCompleteStatus to check whether the transfer tasks "
522	              "that have been created are completed, and then create new transfer tasks.");
523	    return RESOURCE_EXHAUSTED;
524	  }
525	  // 使用 scope_guard 自动管理 flag 资源的释放
526	  HIXL_DISMISSABLE_GUARD(flag_guard, ([this, flag_index]() { ReleaseFlagIndex(flag_index); }));
527	  uint64_t *flag_addr = &flag_queue_[flag_index];
528	  const char *kTransFlagName = nullptr;
529	  if (remote_endpoint_.loc.locType == ENDPOINT_LOC_TYPE_HOST) {
530	    kTransFlagName = kTransFlagNameHost;
531	  } else {
532	    kTransFlagName = kTransFlagNameDevice;
533	  }
534	  HIXL_CHK_HCCL_RET(static_cast<HcclResult>(
535	                        HcommProxy::ReadNbiOnThread(static_cast<ThreadHandle>(0), client_channel_handle_, flag_addr,
536	                                                    tag_mem_descs_[kTransFlagName].addr, kFlagSizeBytes)),
537	                    "[HixlClient] channel_handle:%lu, dst_addr:%p, src_addr:%p, size:%u bytes", client_channel_handle_,
538	                    flag_addr, tag_mem_descs_[kTransFlagName].addr, kFlagSizeBytes);
539	  auto *query_mem_handle = new (std::nothrow) CompleteHandleInfo();
540	  if (query_mem_handle == nullptr) {
541	    HIXL_LOGE(FAILED, "Memory allocate failed; unable to generate query handle.");
542	    return FAILED;
543	  }
544	  query_mem_handle->magic = kRoceCompleteMagic;
545	  query_mem_handle->flag_index = flag_index;
546	  query_mem_handle->flag_address = flag_addr;
547	  // 需要先创建query_handle实体，之后再传给指针。
548	  *query_handle = query_mem_handle;
549	  live_handles_[flag_index] = query_mem_handle;
550	  // 成功后 dismiss guard，避免重复释放
551	  HIXL_DISMISS_GUARD(flag_guard);
552	  return SUCCESS;
553	}
