555	Status HixlCSClient::EnsureDeviceRemoteFlagInited() {
556	  if (device_remote_flag_inited_) {
557	    return SUCCESS;
558	  }
559	  const char *kTransFlagName = nullptr;
560	  if (remote_endpoint_.loc.locType == ENDPOINT_LOC_TYPE_HOST) {
561	    kTransFlagName = kTransFlagNameHost;
562	  } else {
563	    kTransFlagName = kTransFlagNameDevice;
564	  }
565	  const auto it = tag_mem_descs_.find(kTransFlagName);
566	  // tag 不存在时，不报错，保持未初始化状态
567	  // 实际传输时 PrepareDeviceRemoteFlagAndKernel 会检查并报错
568	  if (it == tag_mem_descs_.end()) {
569	    HIXL_LOGD("[HixlClient] builtin remote_flag tag not found: %s, skip initialization", kTransFlagName);
570	    return SUCCESS;
571	  }
572	
573	  const CommMem &mem = it->second;
574	  if (mem.addr == nullptr) {
575	    HIXL_LOGD("[HixlClient] builtin remote_flag addr is null, skip initialization");
576	    return SUCCESS;
577	  }
578	
579	  if (mem.size < static_cast<uint64_t>(sizeof(uint64_t))) {
580	    HIXL_LOGD("[HixlClient] builtin remote_flag size too small. size=%" PRIu64 ", skip initialization", mem.size);
581	    return SUCCESS;
582	  }
583	
584	  device_remote_flag_addr_ = mem.addr;
585	  device_remote_flag_size_ = mem.size;
586	  device_remote_flag_inited_ = true;
587	
588	  HIXL_LOGI("[HixlClient] builtin remote_flag ready. addr=%p u64=%p size=%" PRIu64, mem.addr, device_remote_flag_addr_,
589	            device_remote_flag_size_);
590	  return SUCCESS;
591	}
