593	Status HixlCSClient::ReleaseDevCompleteHandle(DeviceCompleteHandle *handle) {
594	  if (handle == nullptr) {
595	    return SUCCESS;
596	  }
597	  HIXL_LOGI("[HixlCSClient] ReleaseDevCompleteHandle start");
598	  if (handle->magic != kDeviceCompleteMagic) {
599	    HIXL_LOGE(PARAM_INVALID, "[HixlCSClient] ReleaseDevCompleteHandle bad magic=0x%X", handle->magic);
600	    return PARAM_INVALID;
601	  }
602	  (void)pending_device_handles_.erase(handle);
603	
604	  // Free independent host_flag (allocated for async transfers)
605	  if (handle->host_flag != nullptr) {
606	    HIXL_CHK_ACL(aclrtFreeHost(handle->host_flag));
607	    handle->host_flag = nullptr;
608	  }
609	
610	  // Free device op desc buffer
611	  if (handle->dev_op_desc_buf != nullptr) {
612	    HIXL_CHK_ACL(aclrtFree(handle->dev_op_desc_buf));
613	    handle->dev_op_desc_buf = nullptr;
614	  }
615	
616	  // Release shared slot reference
617	  std::shared_ptr<TransferPool::SlotHandle> slot_ref = std::move(handle->shared_slot);
618	  if (slot_ref != nullptr) {
619	    ReleaseSharedSlotRef(slot_ref);
620	  }
621	
622	  handle->magic = 0U;
623	  delete handle;
624	  HIXL_LOGI("[HixlCSClient] ReleaseDevCompleteHandle end");
625	  return SUCCESS;
626	}
