628	Status HixlCSClient::AcquireSharedSlot(std::shared_ptr<TransferPool::SlotHandle> &slot_out) {
629	  // If active slot exists (pending transfer), reuse it
630	  if (active_slot_ != nullptr && active_slot_.use_count() > 0) {
631	    const long ref_before = active_slot_.use_count();
632	    slot_out = active_slot_;  // Share existing slot (increases ref_count)
633	    HIXL_LOGI("[HixlClient] Reusing active slot. slot_index=%u ref_before=%ld ref_after=%ld", active_slot_->slot_index,
634	              ref_before, active_slot_.use_count());
635	    return SUCCESS;
636	  }
637	
638	  // No active slot - acquire new from pool
639	  TransferPool::SlotHandle new_slot{};
640	  auto *pool = TransferPool::GetInstance(device_id_);
641	  HIXL_CHECK_NOTNULL(pool);
642	  HIXL_CHK_STATUS_RET(pool->Acquire(&new_slot), "[HixlClient] Acquire slot from pool failed");
643	
644	  active_slot_ = std::make_shared<TransferPool::SlotHandle>(new_slot);
645	  slot_out = active_slot_;
646	  HIXL_LOGI("[HixlClient] Acquired new slot. slot_index=%u ref_count=%ld", new_slot.slot_index,
647	            active_slot_.use_count());
648	  return SUCCESS;
649	}
650	
651	void HixlCSClient::ReleaseSharedSlotRef(std::shared_ptr<TransferPool::SlotHandle> &slot_ref) {
652	  if (slot_ref == nullptr) {
653	    return;
654	  }
655	  if (active_slot_ == nullptr || active_slot_ != slot_ref) {
656	    slot_ref.reset();
657	    return;
658	  }
659	
660	  const uint32_t slot_index = active_slot_->slot_index;
661	  const long ref_before = active_slot_.use_count();
662	  slot_ref.reset();
663	  HIXL_LOGI("[HixlClient] ReleaseSharedSlotRef. slot_index=%u ref_before=%ld ref_after=%ld", slot_index, ref_before,
664	            active_slot_.use_count());
665	
666	  if (active_slot_.use_count() == 1) {
667	    // Reset err flag only when the shared slot has no pending transfer references.
668	    if (active_slot_->err_flag_host_addr != nullptr) {
669	      *(active_slot_->err_flag_host_addr) = 0U;
670	    }
671	    auto *pool = TransferPool::GetInstance(active_slot_->device_id);
672	    if (pool != nullptr) {
673	      if (transfer_failure_latched_) {
674	        pool->Abort(*active_slot_);
675	        HIXL_LOGI("[HixlClient] Aborted slot on last ref after latched failure. slot_index=%u", slot_index);
676	      } else {
677	        pool->Release(*active_slot_);
678	        HIXL_LOGI("[HixlClient] Released slot to pool. slot_index=%u", slot_index);
679	      }
680	    }
681	    active_slot_.reset();
682	  }
683	}
684	
685	void HixlCSClient::CleanupActiveSlot() {
686	  if (active_slot_ != nullptr) {
687	    auto *abort_pool = TransferPool::GetInstance(active_slot_->device_id);
688	    if (abort_pool != nullptr) {
689	      abort_pool->Abort(*active_slot_);
690	    }
691	    HIXL_LOGI("[HixlClient] Aborted active slot. slot_index=%u", active_slot_->slot_index);
692	    active_slot_.reset();
693	  }
694	}
