720	Status HixlCSClient::LaunchDeviceChunkedKernels(bool is_get, DeviceCompleteHandle &handle, uint32_t list_num) const {
721	  uint32_t num_chunks = (list_num + kMaxKernelBatchSize - 1U) / kMaxKernelBatchSize;
722	  for (uint32_t chunk_idx = 0U; chunk_idx < num_chunks; ++chunk_idx) {
723	    uint32_t chunk_offset = chunk_idx * kMaxKernelBatchSize;
724	    uint32_t chunk_list_num = std::min(kMaxKernelBatchSize, list_num - chunk_offset);
725	    uint32_t chunk_end = chunk_offset + chunk_list_num;
726	    bool need_notify_wait = (chunk_end % kNotifyWaitTaskInterval == 0U) || (chunk_end == list_num);
727	    HixlOneSideOpParam param{};
728	    HIXL_CHK_STATUS_RET(BuildDeviceChunkParam(handle, chunk_offset, chunk_list_num, need_notify_wait, param),
729	                        "BuildDeviceChunkParam failed for chunk %u/%u", chunk_idx, num_chunks);
730	    HIXL_CHK_STATUS_RET(LaunchDeviceKernel(is_get, handle, param, need_notify_wait),
731	                        "LaunchDeviceKernel failed for chunk %u/%u", chunk_idx, num_chunks);
732	  }
733	  return SUCCESS;
734	}
