809	Status HixlCSClient::LaunchDeviceKernel(bool is_get, DeviceCompleteHandle &handle, const HixlOneSideOpParam &param,
810	                                        bool wait_notify) {
811	  const char *kernel_name = is_get ? kDeviceFuncGet : kDeviceFuncPut;
812	  HIXL_LOGI("[HixlClient] LaunchDeviceKernel start. kernel=%s wait_notify=%d", kernel_name, wait_notify);
813	  HIXL_CHECK_NOTNULL(handle.shared_slot.get(), "[HixlClient] LaunchDeviceKernel shared_slot is null");
814	  const ThreadHandle thread = handle.shared_slot->thread;
815	  auto *pool = TransferPool::GetInstance(handle.shared_slot->device_id);
816	  HIXL_CHECK_NOTNULL(pool, "[HixlClient] TransferPool is null for device=%d", handle.shared_slot->device_id);
817	  void *func = pool->GetDeviceKernelFunc(is_get);
818	  HIXL_CHECK_NOTNULL(func, "[HixlClient] func is null for %s", kernel_name);
819	  constexpr uint32_t block_dim = 1U;
820	
821	  aclrtFuncHandle funcHandle = func;
822	  aclrtArgsHandle argsHandle = nullptr;
823	  HIXL_CHK_ACL_RET(aclrtKernelArgsInit(funcHandle, &argsHandle), "[HixlClient] aclrtKernelArgsInit failed. kernel=%s",
824	                   kernel_name);
825	  aclrtParamHandle paraHandle;
826	  HIXL_CHK_ACL_RET(aclrtKernelArgsAppend(argsHandle, const_cast<HixlOneSideOpParam *>(&param),
827	                                         sizeof(HixlOneSideOpParam), &paraHandle),
828	                   "[HixlClient] aclrtKernelArgsAppend param failed, kernel = %s", kernel_name);
829	  HIXL_CHK_ACL_RET(aclrtKernelArgsFinalize(argsHandle), "[HixlClient] aclrtKernelArgsFinalize failed, kernel = %s",
830	                   kernel_name);
831	
832	  aclrtLaunchKernelCfg cfg;
833	  aclrtLaunchKernelAttr attr;
834	  attr.id = ACL_RT_LAUNCH_KERNEL_ATTR_TIMEOUT;
835	  attr.value.timeout = kNotifyDefaultWaitTimeS;
836	  cfg.numAttrs = 1;
837	  cfg.attrs = &attr;
838	
839	  HIXL_CHK_ACL_RET(
840	      aclrtLaunchKernelWithConfig(funcHandle, block_dim, handle.shared_slot->stream, &cfg, argsHandle, nullptr),
841	      "[HixlClient] aclrtLaunchKernelWithConfig failed, kernel=%s, thread=%lu", kernel_name,
842	      static_cast<uint64_t>(thread));
843	  if (wait_notify) {
844	    HIXL_CHK_ACL_RET(aclrtWaitAndResetNotify(handle.shared_slot->notify, handle.shared_slot->stream, kCustomTimeoutMs),
845	                     "[HixlClient] aclrtWaitAndResetNotify failed, kernel=%s, thread=%lu", kernel_name,
846	                     static_cast<uint64_t>(thread));
847	  }
848	  HIXL_LOGI("[HixlClient] LaunchDeviceKernel end. kernel=%s", kernel_name);
849	  return SUCCESS;
850	}
