852	Status HixlCSClient::BatchTransferDeviceAsync(bool is_get, uint32_t list_num, const HixlOneSideOpDesc *desc_list,
853	                                              void **query_handle) {
854	  void *handle_ptr = nullptr;
855	  HIXL_CHK_STATUS_RET(ValidateDeviceInputs(list_num, desc_list, handle_ptr), "ValidateDeviceInputs failed");
856	
857	  std::shared_ptr<TransferPool::SlotHandle> slot;
858	  HIXL_CHK_STATUS_RET(AcquireSharedSlot(slot), "[HixlClient] AcquireSharedSlot failed");
859	  HIXL_DISMISSABLE_GUARD(slot_guard, ([this, &slot]() { ReleaseSharedSlotRef(slot); }));
860	
861	  HIXL_CHECK_NOTNULL(slot->notify, "[HixlClient] slot->notify is null");
862	
863	  void *host_flag = nullptr;
864	  HIXL_CHK_STATUS_RET(AllocateHostFlag(host_flag), "[HixlClient] AllocateHostFlag failed");
865	  HIXL_DISMISSABLE_GUARD(flag_guard, [&host_flag]() {
866	    if (host_flag != nullptr) {
867	      aclrtFreeHost(host_flag);
868	    }
869	  });
870	
871	  auto *handle = new (std::nothrow) DeviceCompleteHandle();
872	  HIXL_CHK_BOOL_RET_STATUS(handle != nullptr, FAILED, "[HixlClient] Allocate DeviceCompleteHandle failed");
873	  HIXL_DISMISSABLE_GUARD(handle_guard, ([this, handle]() { (void)ReleaseDevCompleteHandle(handle); }));
874	  handle->magic = kDeviceCompleteMagic;
875	  handle->reserved = 0U;
876	  handle->shared_slot = std::move(slot);
877	  HIXL_DISMISS_GUARD(slot_guard);
878	  handle->host_flag = host_flag;
879	  handle->dev_op_desc_buf = nullptr;
880	  HIXL_DISMISS_GUARD(flag_guard);
881	
882	  HIXL_CHK_STATUS_RET(AllocateDeviceDescBuf(*handle, list_num, desc_list), "AllocateDeviceDescBuf failed");
883	
884	  HIXL_LOGI("[HixlClient] BatchTransferDeviceAsync. is_get=%d list_num=%u slot=%u magic=%u",
885	            static_cast<int32_t>(is_get), list_num, handle->shared_slot->slot_index, handle->magic);
886	
887	  {
888	    hixl::TemporaryRtContext ctx_guard(handle->shared_slot->ctx);
889	    HIXL_CHK_STATUS_RET(LaunchDeviceChunkedKernels(is_get, *handle, list_num),
890	                        "[HixlClient] LaunchDeviceChunkedKernels failed, is_get=%d, list_num=%u, slot=%u, thread=%lu",
891	                        static_cast<int32_t>(is_get), list_num, handle->shared_slot->slot_index,
892	                        static_cast<uint64_t>(handle->shared_slot->thread));
893	    HIXL_CHK_ACL_RET(aclrtMemcpyAsync(handle->host_flag, sizeof(uint64_t), handle->shared_slot->dev_const_one,
894	                                      sizeof(uint64_t), ACL_MEMCPY_DEVICE_TO_HOST, handle->shared_slot->stream),
895	                     "[HixlClient] aclrtMemcpyAsync (Flag D2H) failed, is_get=%d, list_num=%u, slot=%u, thread=%lu",
896	                     static_cast<int32_t>(is_get), list_num, handle->shared_slot->slot_index,
897	                     static_cast<uint64_t>(handle->shared_slot->thread));
898	  }
899	
900	  *query_handle = static_cast<void *>(handle);
901	  HIXL_DISMISS_GUARD(handle_guard);
902	  HIXL_LOGI("[HixlClient] BatchTransfer submitted. is_get=%d list_num=%u slot=%u", static_cast<int32_t>(is_get),
903	            list_num, handle->shared_slot->slot_index);
904	  pending_device_handles_.insert(handle);
905	  return SUCCESS;
906	}
