908	Status HixlCSClient::BatchTransferDeviceSync(bool is_get, uint32_t list_num, const HixlOneSideOpDesc *desc_list,
909	                                             uint32_t timeout_ms) {
910	  void *handle_ptr = nullptr;
911	  HIXL_CHK_STATUS_RET(ValidateDeviceInputs(list_num, desc_list, handle_ptr), "ValidateDeviceInputs failed");
912	
913	  std::shared_ptr<TransferPool::SlotHandle> slot;
914	  HIXL_CHK_STATUS_RET(AcquireSharedSlot(slot), "[HixlClient] AcquireSharedSlot failed");
915	  HIXL_DISMISSABLE_GUARD(slot_guard, ([this, &slot]() { ReleaseSharedSlotRef(slot); }));
916	  HIXL_CHECK_NOTNULL(slot->notify, "[HixlClient] slot->notify is null");
917	
918	  auto *handle = new (std::nothrow) DeviceCompleteHandle();
919	  HIXL_CHK_BOOL_RET_STATUS(handle != nullptr, FAILED, "[HixlClient] Allocate DeviceCompleteHandle failed");
920	  HIXL_MAKE_GUARD(handle_guard, ([this, handle]() { (void)ReleaseDevCompleteHandle(handle); }));
921	  handle->magic = kDeviceCompleteMagic;
922	  handle->reserved = 0U;
923	  handle->shared_slot = std::move(slot);
924	  HIXL_DISMISS_GUARD(slot_guard);
925	  handle->host_flag = nullptr;
926	  handle->dev_op_desc_buf = nullptr;
927	
928	  HIXL_CHK_STATUS_RET(AllocateDeviceDescBuf(*handle, list_num, desc_list), "AllocateDeviceDescBuf failed");
929	
930	  HIXL_LOGI("[HixlClient] BatchTransferDeviceSync. is_get=%d list_num=%u slot=%u", static_cast<int32_t>(is_get),
931	            list_num, handle->shared_slot->slot_index);
932	
933	  {
934	    hixl::TemporaryRtContext ctx_guard(handle->shared_slot->ctx);
935	    HIXL_CHK_STATUS_RET(LaunchDeviceChunkedKernels(is_get, *handle, list_num),
936	                        "[HixlClient] LaunchDeviceChunkedKernels failed, is_get=%d, list_num=%u, slot=%u, thread=%lu",
937	                        static_cast<int32_t>(is_get), list_num, handle->shared_slot->slot_index,
938	                        static_cast<uint64_t>(handle->shared_slot->thread));
939	    const aclError sync_ret = aclrtSynchronizeStreamWithTimeout(handle->shared_slot->stream, timeout_ms);
940	    const ThreadHandle thread = handle->shared_slot->thread;
941	    const uint32_t slot_index = handle->shared_slot->slot_index;
942	    if (sync_ret != ACL_SUCCESS && handle->shared_slot != nullptr) {
943	      auto *pool = TransferPool::GetInstance(handle->shared_slot->device_id);
944	      if (pool != nullptr) {
945	        pool->Abort(*handle->shared_slot);
946	      }
947	    }
948	    HIXL_CHK_ACL_RET(sync_ret,
949	                     "[HixlClient] aclrtSynchronizeStreamWithTimeout failed, kernel=%s, list_num=%u, slot=%u, "
950	                     "thread=%lu",
951	                     is_get ? kDeviceFuncGet : kDeviceFuncPut, list_num, slot_index, static_cast<uint64_t>(thread));
952	  }
953	
954	  HIXL_LOGI("[HixlClient] BatchTransferDeviceSync done. is_get=%d list_num=%u", static_cast<int32_t>(is_get), list_num);
955	  return SUCCESS;
956	}
