958	Status HixlCSClient::BatchTransferHostSync(bool is_get, uint32_t list_num, const HixlOneSideOpDesc *desc_list,
959	                                           uint32_t timeout_ms) {
960	  void *raw_handle = nullptr;
961	  HIXL_CHK_STATUS_RET(BatchTransferHostAsync(is_get, list_num, desc_list, &raw_handle),
962	                      "[HixlClient] BatchTransferHostAsync failed");
963	  HIXL_CHECK_NOTNULL(raw_handle);
964	  const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(timeout_ms);
965	  while (true) {
966	    if (std::chrono::steady_clock::now() >= deadline) {
967	      (void)ReleaseCompleteHandle(static_cast<CompleteHandleInfo *>(raw_handle));
968	      HIXL_LOGE(TIMEOUT, "[HixlClient] BatchTransferHostSync timeout after %u ms", timeout_ms);
969	      return TIMEOUT;
970	    }
971	    HixlCompleteStatus st = HixlCompleteStatus::HIXL_COMPLETE_STATUS_WAITING;
972	    const Status cs = CheckStatusLocked(raw_handle, &st);
973	    if (cs != SUCCESS) {
974	      (void)ReleaseCompleteHandle(static_cast<CompleteHandleInfo *>(raw_handle));
975	      return cs;
976	    }
977	    if (st == HixlCompleteStatus::HIXL_COMPLETE_STATUS_COMPLETED) {
978	      return SUCCESS;
979	    }
980	    constexpr auto kSyncQueryIntervalUs = 10U;
981	    std::this_thread::sleep_for(std::chrono::microseconds(kSyncQueryIntervalUs));
982	  }
983	}
