985	Status HixlCSClient::BatchTransferSync(bool is_get, uint32_t list_num, const HixlOneSideOpDesc *desc_list,
986	                                       uint32_t timeout_ms) {
987	  std::lock_guard<std::mutex> lock(mutex_);
988	  HIXL_CHK_BOOL_RET_STATUS(!transfer_failure_latched_, FAILED,
989	                           "[HixlClient] BatchTransferSync rejected after prior transfer failure. last_status=%u, "
990	                           "is_get=%d, list_num=%u",
991	                           static_cast<uint32_t>(transfer_failure_status_), static_cast<int32_t>(is_get), list_num);
992	  auto ctx_guard = GetContextGuard();
993	  (void)ctx_guard;
994	  HIXL_CHK_STATUS_RET(ValidateAddress(list_num, desc_list), "[HixlClient] ValidateAddress failed.");
995	  HIXL_CHECK_NOTNULL(local_endpoint_);
996	  const EndpointDesc endpoint = local_endpoint_->GetEndpoint();
997	  Status ret = FAILED;
998	  if (IsDeviceEndpoint(endpoint)) {
999	    if (local_endpoint_->NeedHostVaMapping()) {
1000	      std::vector<HixlOneSideOpDesc> mutable_descs(desc_list, desc_list + list_num);
1001	      HIXL_CHK_STATUS_RET(ConvertHostMappedDescs(list_num, mutable_descs.data()),
1002	                          "[HixlClient] convert host mapped descs failed.");
1003	      ret = BatchTransferDeviceSync(is_get, list_num, mutable_descs.data(), timeout_ms);
1004	    } else {
1005	      ret = BatchTransferDeviceSync(is_get, list_num, desc_list, timeout_ms);
1006	    }
1007	  } else if (endpoint.loc.locType == ENDPOINT_LOC_TYPE_HOST) {
1008	    ret = BatchTransferHostSync(is_get, list_num, desc_list, timeout_ms);
1009	  } else {
1010	    HIXL_LOGE(PARAM_INVALID, "[HixlClient] Invalid endpoint location: %d", endpoint.loc.locType);
1011	    return PARAM_INVALID;
1012	  }
1013	  HIXL_CHK_STATUS_RET(LatchTransferFailureIfNeeded(ret),
1014	                      "[HixlClient] BatchTransferSync failed, is_get=%d, list_num=%u, local=[%s], remote=[%s]",
1015	                      static_cast<int32_t>(is_get), list_num, EndpointToString(endpoint).c_str(),
1016	                      EndpointToString(remote_endpoint_).c_str());
1017	  HIXL_LOGI("[HixlClient] BatchTransferSync success, is_get=%d, list_num=%u", static_cast<int32_t>(is_get), list_num);
1018	  return SUCCESS;
1019	}
