1039	    if (local_endpoint_->NeedHostVaMapping()) {
1040	      std::vector<HixlOneSideOpDesc> mutable_descs(desc_list, desc_list + list_num);
1041	      HIXL_CHK_STATUS_RET(ConvertHostMappedDescs(list_num, mutable_descs.data()),
1042	                          "[HixlClient] convert host mapped descs failed.");
1043	      ret = BatchTransferDeviceAsync(is_get, list_num, mutable_descs.data(), query_handle);
1044	    } else {
1045	      ret = BatchTransferDeviceAsync(is_get, list_num, desc_list, query_handle);
1046	    }
1047	  } else if (ep.loc.locType == ENDPOINT_LOC_TYPE_HOST) {
1048	    ret = BatchTransferHostAsync(is_get, list_num, desc_list, query_handle);
1049	  } else {
1050	    HIXL_LOGE(PARAM_INVALID, "[HixlClient] Invalid endpoint location: %d", ep.loc.locType);
1051	    return PARAM_INVALID;
1052	  }
1053	  HIXL_CHK_STATUS_RET(LatchTransferFailureIfNeeded(ret),
1054	                      "[HixlClient] BatchTransferAsync failed, is_get=%d, list_num=%u, local=[%s], remote=[%s]",
1055	                      static_cast<int32_t>(is_get), list_num, EndpointToString(ep).c_str(),
1056	                      EndpointToString(remote_endpoint_).c_str());
1057	  HIXL_LOGI("[HixlClient] BatchTransferAsync success, is_get=%d, list_num=%u", static_cast<int32_t>(is_get), list_num);
1058	  return SUCCESS;
1059	}
