1061	Status HixlCSClient::CheckStatusHost(CompleteHandleInfo &query_handle, HixlCompleteStatus &status) {
1062	  // 检验query_handle中的序号是否合规
1063	  if (query_handle.flag_index < 0 || query_handle.flag_index >= static_cast<int32_t>(kFlagQueueSize)) {
1064	    HIXL_LOGE(PARAM_INVALID,
1065	              "The value of query_handle->flag_index is outside the valid verification range; please check the "
1066	              "query_handle. query_handle->flag_index:%d",
1067	              query_handle.flag_index);
1068	    return PARAM_INVALID;
1069	  }
1070	  // 通过读取query_handle中地址的值，来判断任务的完成状态
1071	  HIXL_CHECK_NOTNULL(query_handle.flag_address);
1072	  volatile uint64_t *flag_ptr = query_handle.flag_address;
1073	  const uint64_t flag_val = *flag_ptr;
1074	  // 查到flag变成1之后，就把其重置为0，之后告知用户读写任务已经完成。
1075	  if (flag_val == kFlagDoneValue) {
1076	    status = HixlCompleteStatus::HIXL_COMPLETE_STATUS_COMPLETED;
1077	    HIXL_LOGI("The current transmission task has been completed.");
1078	    return ReleaseCompleteHandle(&query_handle);  // 释放内存并回收索引
1079	  }
1080	  status = HixlCompleteStatus::HIXL_COMPLETE_STATUS_WAITING;
1081	  HIXL_LOGI("The current transmission task has not been completed.");
1082	  return SUCCESS;
1083	}
1084	
1085	Status HixlCSClient::CheckStatusDevice(DeviceCompleteHandle &query_handle, HixlCompleteStatus &status) {
1086	  if (query_handle.magic != kDeviceCompleteMagic) {
1087	    HIXL_LOGE(PARAM_INVALID, "[HixlClient] CheckStatusUb bad magic=0x%X", query_handle.magic);
1088	    return PARAM_INVALID;
1089	  }
1090	  HIXL_CHECK_NOTNULL(query_handle.shared_slot.get(), "[HixlClient] CheckStatusDevice shared_slot is null");
1091	  HIXL_CHECK_NOTNULL(query_handle.host_flag, "[HixlClient] CheckStatusDevice host_flag is null");
1092	
1093	  volatile uint64_t *flag_ptr = static_cast<uint64_t *>(query_handle.host_flag);
1094	  const uint64_t flag_val = *flag_ptr;
1095	  HIXL_LOGI("[HixlCSClient] CheckStatusDevice flag_val=%lu", flag_val);
1096	  if (flag_val == kDeviceFlagDoneValue) {
1097	    status = HixlCompleteStatus::HIXL_COMPLETE_STATUS_COMPLETED;
1098	    HIXL_LOGI("[HixlClient] Batch completed. slot=%u", query_handle.shared_slot->slot_index);
1099	    return ReleaseDevCompleteHandle(&query_handle);
1100	  }
1101	
1102	  if (transfer_failure_latched_) {
1103	    status = HixlCompleteStatus::HIXL_COMPLETE_STATUS_FAILED;
1104	    HIXL_LOGE(transfer_failure_status_,
1105	              "[HixlClient] CheckStatusDevice failed due to latched transfer failure. status=%u slot=%u",
1106	              static_cast<uint32_t>(transfer_failure_status_), query_handle.shared_slot->slot_index);
1107	    return ReleaseDevCompleteHandle(&query_handle);
1108	  }
1109	
1110	  if (query_handle.shared_slot->err_flag_host_addr != nullptr && *query_handle.shared_slot->err_flag_host_addr != 0U) {
1111	    LatchTransferFailure(FAILED);
1112	    status = HixlCompleteStatus::HIXL_COMPLETE_STATUS_FAILED;
1113	    HIXL_LOGE(FAILED, "[HixlClient] err_flag set. slot=%u thread=%" PRIu64 " channel=%" PRIu64,
1114	              query_handle.shared_slot->slot_index, static_cast<uint64_t>(query_handle.shared_slot->thread),
1115	              static_cast<uint64_t>(client_channel_handle_));
1116	    return ReleaseDevCompleteHandle(&query_handle);
1117	  }
1118	
1119	  status = HixlCompleteStatus::HIXL_COMPLETE_STATUS_WAITING;
1120	  return SUCCESS;
1121	}
