1128	
1129	Status HixlCSClient::CheckStatusLocked(void *query_handle, HixlCompleteStatus *status) {
1130	  auto ctx_guard = GetContextGuard();
1131	  (void)ctx_guard;
1132	  HIXL_CHECK_NOTNULL(query_handle);
1133	  HIXL_CHECK_NOTNULL(status);
1134	
1135	  uint32_t head = 0U;
1136	  errno_t rc = memcpy_s(&head, sizeof(head), query_handle, sizeof(head));
1137	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, FAILED,
1138	                           "[HixlClient] Call api:memcpy_s failed, ret:%d, src:%p, src_size:%zu bytes, "
1139	                           "dst_size:%zu bytes",
1140	                           static_cast<int32_t>(rc), query_handle, sizeof(head), sizeof(head));
1141	
1142	  if (head == kDeviceCompleteMagic) {
1143	    DeviceCompleteHandle *device_handle = static_cast<DeviceCompleteHandle *>(query_handle);
1144	    return CheckStatusDevice(*device_handle, *status);
1145	  }
1146	
1147	  if (head == kRoceCompleteMagic) {
1148	    CompleteHandleInfo *legacy = static_cast<CompleteHandleInfo *>(query_handle);
1149	    return CheckStatusHost(*legacy, *status);
1150	  }
1151	
1152	  HIXL_LOGE(PARAM_INVALID, "[HixlClient] CheckStatus bad magic=0x%X", head);
1153	  return PARAM_INVALID;
1154	}
