1196	Status HixlCSClient::ExchangeEndpointAndCreateChannel(uint32_t timeout_ms) {
1197	  const EndpointDesc &src_ep = local_endpoint_->GetEndpoint();
1198	  HIXL_LOGD(
1199	      "[HixlClient] MatchEndpoint then CreateChannel. socket: %d, timeout: %u ms, "
1200	      "Src[protocol:%s, type:%d, id:%u], Dst[protocol:%s, type:%d, id:%u]",
1201	      socket_, timeout_ms, ProtocolToString(src_ep.protocol).c_str(), static_cast<int32_t>(src_ep.commAddr.type),
1202	      src_ep.commAddr.id, ProtocolToString(remote_endpoint_.protocol).c_str(),
1203	      static_cast<int32_t>(remote_endpoint_.commAddr.type), remote_endpoint_.commAddr.id);
1204	  HIXL_CHK_STATUS_RET(ConnMsgHandler::SendMatchEndpointRequest(socket_, remote_endpoint_),
1205	                      "[HixlClient] SendMatchEndpointRequest failed. fd=%d", socket_);
1206	  uint32_t remote_listen_port = 0;
1207	  uint64_t channel_index = 0UL;
1208	  HIXL_CHK_STATUS_RET(ConnMsgHandler::RecvMatchEndpointResponse(socket_, remote_endpoint_handle_, remote_listen_port,
1209	                                                                channel_index, timeout_ms),
1210	                      "[HixlClient] RecvMatchEndpointResponse failed. fd=%d, timeout=%u ms", socket_, timeout_ms);
1211	  local_endpoint_->SetPort(remote_listen_port);
1212	  CommMem *prefetch_mems = nullptr;
1213	  char **prefetch_tags = nullptr;
1214	  uint32_t prefetch_num = 0U;
1215	  HIXL_LOGI("[HixlClient] Connect: prefetch remote mem before CreateChannel");
1216	  HIXL_CHK_STATUS_RET(GetRemoteMemImpl(timeout_ms, &prefetch_mems, &prefetch_tags, &prefetch_num),
1217	                      "[HixlClient] Connect prefetch GetRemoteMem/Import failed. fd=%d, timeout=%u ms", socket_,
1218	                      timeout_ms);
1219	  CreateChannelReq create_body{
1220	      src_ep,     remote_endpoint_handle_, tc_,           sl_,
1221	      retry_cnt_, retry_interval_,         channel_index, global_config_.Qos().value_or(kQosDefault),
1222	      timeout_ms};
1223	  HIXL_CHK_STATUS_RET(ConnMsgHandler::SendCreateChannelRequest(socket_, create_body),
1224	                      "[HixlClient] SendCreateChannelRequest failed. fd=%d", socket_);
1225	  ChannelHandle channel_handle = 0UL;
1226	  ChannelDesc channel_desc{remote_endpoint_,
1227	                           tc_,
1228	                           sl_,
1229	                           retry_cnt_,
1230	                           retry_interval_,
1231	                           ChannelType::kClient,
1232	                           channel_index,
1233	                           global_config_.Qos().value_or(kQosDefault)};
1234	  HIXL_CHK_STATUS_RET(local_endpoint_->CreateChannel(channel_desc, channel_handle, timeout_ms),
1235	                      "[HixlClient] Endpoint CreateChannel failed. Dst[id:0x%x]", remote_endpoint_.commAddr.id);
1236	  HIXL_CHK_STATUS_RET(ConnMsgHandler::RecvCreateChannelResponse(socket_, timeout_ms),
1237	                      "[HixlClient] RecvCreateChannelResponse failed. fd=%d, timeout=%u ms", socket_, timeout_ms);
1238	  HIXL_LOGI("[HixlClient] Connect: remote endpoint handle = %" PRIu64, remote_endpoint_handle_);
1239	  client_channel_handle_ = channel_handle;
1240	  HIXL_LOGI("[HixlClient] Channel Ready. client_channel_handle_=%p", client_channel_handle_);
1241	  return SUCCESS;
1242	}
