1333	Status HixlCSClient::ImportRemoteMem(std::vector<HixlMemDesc> &desc_list, CommMem **remote_mem_list,
1334	                                     char ***mem_tag_list, uint32_t *list_num) {
1335	  HIXL_DISMISSABLE_GUARD(free_export_desc, [&desc_list]() { FreeExportDesc(desc_list); });
1336	  *list_num = static_cast<uint32_t>(desc_list.size());
1337	  HIXL_CHK_STATUS_RET(ClearRemoteMemInfo(), "[HixlClient] ClearRemoteMemInfo before ImportRemoteMem failed");
1338	  if (*list_num == 0U) {
1339	    HIXL_LOGI("[HixlClient] Remote mem list is empty, nothing to import.");
1340	    return SUCCESS;
1341	  }
1342	  HIXL_CHK_STATUS_RET(ValidateExportDescList(desc_list), "[HixlClient] ValidateExportDescList failed");
1343	  HIXL_CHECK_NOTNULL(local_endpoint_);
1344	  EndpointHandle ep_handle = local_endpoint_->GetHandle();
1345	  HIXL_CHECK_NOTNULL(ep_handle, "[HixlClient] ImportRemoteMem: endpoint handle is null");
1346	  ImportCtx ctx;
1347	  ctx.ep = local_endpoint_.get();
1348	  ctx.ep_handle = ep_handle;
1349	  ctx.store = &mem_store_;
1350	  ctx.num = *list_num;
1351	  ctx.imported.reserve(ctx.num);
1352	  ctx.recorded_addrs.reserve(ctx.num);
1353	  ctx.mems.reserve(ctx.num);
1354	  ctx.tag_storage.reserve(ctx.num);
1355	  Status ret = ImportAllDescs(ctx, desc_list);
1356	  if (ret != SUCCESS) {
1357	    HIXL_LOGW("[HixlClient] RollbackImport triggered. Cleaning up %zu imported bufs.", desc_list.size());
1358	    CloseImportedBufs(ctx.ep_handle, desc_list);
1359	    return ret;
1360	  }
1361	  desc_list_ = std::move(desc_list);
1362	  FillOutputParams(ctx, remote_mem_list, mem_tag_list, list_num);
1363	  HIXL_DISMISS_GUARD(free_export_desc);
1364	  return SUCCESS;
1365	}
