1367	Status HixlCSClient::ClearRemoteMemInfo() {
1368	  EndpointHandle ep_handle = (local_endpoint_ != nullptr) ? local_endpoint_->GetHandle() : nullptr;
1369	  const size_t buf_cnt = imported_remote_bufs_.size();
1370	  const size_t addr_cnt = recorded_remote_addrs_.size();
1371	  if (buf_cnt > 0U || addr_cnt > 0U) {
1372	    HIXL_LOGI("[HixlClient] Cleaning up remote mem info. Bufs=%zu, Addrs=%zu", buf_cnt, addr_cnt);
1373	  }
1374	  if (!desc_list_.empty()) {
1375	    if (ep_handle != nullptr) {
1376	      CloseImportedBufs(ep_handle, desc_list_);
1377	    } else {
1378	      HIXL_LOGW("[HixlClient] ClearRemoteMemInfo: endpoint handle null, skip MemClose for %zu bufs", desc_list_.size());
1379	    }
1380	    for (auto &desc : desc_list_) {
1381	      if (desc.export_desc != nullptr) {
1382	        std::free(desc.export_desc);
1383	        desc.export_desc = nullptr;
1384	      }
1385	    }
1386	    desc_list_.clear();
1387	  }
1388	  if (!recorded_remote_addrs_.empty()) {
1389	    UnrecordAddrs(mem_store_, recorded_remote_addrs_);
1390	  }
1391	  tag_mem_descs_.clear();
1392	  remote_mems_out_.clear();
1393	  remote_tag_ptrs_.clear();
1394	  remote_tag_storage_.clear();
1395	  device_remote_flag_inited_ = false;
1396	  device_remote_flag_addr_ = nullptr;
1397	  device_remote_flag_size_ = 0ULL;
1398	  return SUCCESS;
1399	}
