1401	void HixlCSClient::ReleaseLegacyHandles() {
1402	  uint32_t live_cnt = 0U;
1403	  for (size_t i = 0U; i < kFlagQueueSize; ++i) {
1404	    if (live_handles_[i] != nullptr) {
1405	      live_cnt += 1U;
1406	    }
1407	  }
1408	  if (live_cnt > 0U) {
1409	    HIXL_LOGW("[HixlClient] Destroy: %u legacy complete_handle still live. Force releasing them.", live_cnt);
1410	    for (size_t i = 0U; i < kFlagQueueSize; ++i) {
1411	      if (live_handles_[i] != nullptr) {
1412	        delete live_handles_[i];
1413	        live_handles_[i] = nullptr;
1414	      }
1415	    }
1416	    for (size_t i = 0U; i < kFlagQueueSize; ++i) {
1417	      available_indices_[i] = static_cast<int32_t>(i);
1418	    }
1419	    top_index_ = kFlagQueueSize;
1420	  }
1421	}
1422	
1423	void HixlCSClient::AbortAllPendingDeviceHandles() {
1424	  if (pending_device_handles_.empty()) {
1425	    return;
1426	  }
1427	  std::vector<DeviceCompleteHandle *> pending(pending_device_handles_.begin(), pending_device_handles_.end());
1428	  pending_device_handles_.clear();
1429	  for (DeviceCompleteHandle *h : pending) {
1430	    if (h == nullptr) {
1431	      continue;
1432	    }
1433	    if (h->shared_slot != nullptr) {
1434	      auto *pool = TransferPool::GetInstance(h->shared_slot->device_id);
1435	      if (pool != nullptr) {
1436	        pool->Abort(*h->shared_slot);
1437	      }
1438	    }
1439	    (void)ReleaseDevCompleteHandle(h);
1440	  }
1441	}
1442	
1443	void HixlCSClient::ReleaseDeviceResources() {
1444	  for (size_t i = 0U; i < notify_mem_handles_.size(); ++i) {
1445	    if (notify_mem_handles_[i] != nullptr) {
1446	      if (local_endpoint_ != nullptr) {
1447	        local_endpoint_->DeregisterMem(notify_mem_handles_[i]);
1448	      }
1449	      notify_mem_handles_[i] = nullptr;
1450	    }
1451	  }
1452	  notify_mem_handles_.clear();
1453	  CleanupActiveSlot();
1454	}
1455	
1456	Status HixlCSClient::Destroy() {
1457	  std::lock_guard<std::mutex> lock(mutex_);
1458	  Status first_error = SUCCESS;
1459	  {
1460	    auto ctx_guard = GetContextGuard();
1461	    (void)ctx_guard;
1462	    HIXL_EVENT("[HixlClient] Destroy start. fd=%d, imported_bufs=%zu, recorded_addrs=%zu", socket_,
1463	               imported_remote_bufs_.size(), recorded_remote_addrs_.size());
1464	    ReleaseLegacyHandles();
1465	    AbortAllPendingDeviceHandles();
1466	    ReleaseDeviceResources();
1467	    Status ret = ClearRemoteMemInfo();
1468	    if (ret != SUCCESS) {
1469	      HIXL_LOGW("[HixlClient] ClearRemoteMemInfo failed. fd=%d, ret=%u", socket_, static_cast<uint32_t>(ret));
1470	      first_error = (first_error == SUCCESS) ? ret : first_error;
1471	    }
1472	    if (socket_ != -1) {
1473	      HIXL_LOGI("[HixlClient] Closing socket. fd=%d", socket_);
1474	      close(socket_);
1475	      socket_ = -1;
1476	    }
1477	    if (local_endpoint_ != nullptr) {
1478	      ret = local_endpoint_->Finalize();
1479	      if (ret != SUCCESS) {
1480	        HIXL_LOGW("[HixlClient] Finalize endpoint failed in Destroy. ep_handle=%p, ret=%u",
1481	                  local_endpoint_->GetHandle(), static_cast<uint32_t>(ret));
1482	        first_error = (first_error == SUCCESS) ? ret : first_error;
1483	      }
1484	      local_endpoint_.reset();
1485	    }
1486	  }
1487	  // ctx_guard 已析构，TransferPool 放到最后销毁
1488	  if (device_id_ >= 0) {
1489	    auto *pool = TransferPool::GetInstance(device_id_);
1490	    if (pool != nullptr) {
1491	      pool->Finalize();
1492	    }
1493	    device_id_ = -1;
1494	  }
1495	  HIXL_EVENT("[HixlClient] Destroy done. first_error=%u", static_cast<uint32_t>(first_error));
1496	  return first_error;
1497	}
1498	}  // namespace hixl
